  initPageNavigation();
  initFirebaseAuthAndProfile();
  syncDefaultDay();
  updateTodayStatus();
  renderDetailedSchedule(currentSelectedDay);
  renderSchedule();
  renderDate();
  initNav();
  initHomeworksManager();
